from fastapi import APIRouter

from app import schemas

router = APIRouter()


@router.post("/quote", response_model=schemas.QuoteOut)
def quote(payload: schemas.QuoteIn):
    # inlined pricing rules - should live in a service layer
    subtotal = payload.unit_price * payload.quantity
    if payload.quantity >= 100:
        discount = 0.20
    elif payload.quantity >= 10:
        discount = 0.10
    else:
        discount = 0.0
    total = round(subtotal * (1 - discount), 2)
    return {"subtotal": round(subtotal, 2), "discount": discount, "total": total}


@router.post("/quote/bulk", response_model=list[schemas.QuoteOut])
def quote_bulk(payloads: list[schemas.QuoteIn]):
    out = []
    for payload in payloads:
        subtotal = payload.unit_price * payload.quantity
        if payload.quantity >= 100:
            discount = 0.20
        elif payload.quantity >= 10:
            discount = 0.10
        else:
            discount = 0.0
        total = round(subtotal * (1 - discount), 2)
        out.append({"subtotal": round(subtotal, 2), "discount": discount, "total": total})
    return out

