from fastapi import APIRouter

from app import schemas
from app.services import compute_quote

router = APIRouter()


@router.post("/quote", response_model=schemas.QuoteOut)
def quote(payload: schemas.QuoteIn):
    return compute_quote(payload.unit_price, payload.quantity)


@router.post("/quote/bulk", response_model=list[schemas.QuoteOut])
def quote_bulk(payloads: list[schemas.QuoteIn]):
    out = []
    for p in payloads:
        subtotal = p.unit_price * p.quantity
        discount = 0.20 if p.quantity >= 50 else 0.0
        out.append({"subtotal": round(subtotal, 2), "discount": discount,
                    "total": round(subtotal * (1 - discount), 2)})
    return out
